import { existsSync } from 'node:fs';

import AxeBuilder from '@axe-core/playwright';

import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

// `@visual` baselines and axe for the obligation queue (#68): light and dark at 360, 768 and
// 1280 px, and zero serious or critical axe violations in each state. Baselines are only ever
// generated by the e2e workflow's `update_snapshots` dispatch (see e2e/README.md).
const QUEUE = '/w/chennai-solo/obligations';
const WIDTHS = [360, 768, 1280] as const;
const STATES = ['default', 'empty', 'denied', 'offline'] as const;

for (const theme of ['light', 'dark'] as const) {
  for (const width of WIDTHS) {
    test(
      `obligations ${theme} ${String(width)}`,
      { tag: '@visual' },
      async ({ page, asUser }, testInfo) => {
        const name = `obligations-${theme}-${String(width)}.png`;
        test.skip(
          testInfo.config.updateSnapshots === 'none' &&
            !existsSync(testInfo.snapshotPath(name, { kind: 'screenshot' })),
          'no baseline yet: dispatch the e2e workflow with update_snapshots',
        );
        await page.setViewportSize({ width, height: 900 });
        await page.emulateMedia({ colorScheme: theme });
        await asUser('owner', { path: QUEUE });
        await shellReady(page);
        await expect(page).toHaveScreenshot(name, { fullPage: true });
      },
    );
  }
}

for (const state of STATES) {
  test(`obligations axe ${state}`, { tag: '@a11y' }, async ({ page, asUser }) => {
    await asUser('owner', { path: state === 'default' ? QUEUE : `${QUEUE}?__state=${state}` });
    await shellReady(page);
    const { violations } = await new AxeBuilder({ page }).analyze();
    expect(violations.filter((v) => v.impact === 'serious' || v.impact === 'critical')).toEqual([]);
  });
}
